solution:
const m = [[1,2,3],[4,5,6],[7,8,9]];
const target = 5;
for (let i = 0; i < 3; i++) {
  for (let j = 0; j < 3; j++) {
    if (m[i][j] === target) {
      console.log('Found at ' + i + ',' + j);
    }
  }
}
